pragma solidity >=0.8.0;

contract StringBytesIndexedEventProbe {
    event Dyn(string indexed marker, string val, bytes data);

    uint256 public emitCount;
    string public lastVal;
    bytes public lastData;

    function log(string memory marker, string memory val, bytes memory data) external {
        emitCount += 1;
        lastData = data;
        lastVal = val;
        emit Dyn(marker, val, data);
    }
}
